import pathlib,json,copy,urllib.parse,math,re
def unique(pairs):
 d={}
 for k,v in pairs:
  if k in d:raise ValueError('duplicate key: '+k)
  d[k]=v
 return d
def load(name):return json.loads(pathlib.Path(name).read_text(encoding='utf-8'),object_pairs_hook=unique)

BASE={'dashboard.json': {'id': None, 'uid': 'service-main', 'title': 'Service', 'schemaVersion': 39, 'version': 3, 'timezone': 'utc', 'time': {'from': 'now-6h', 'to': 'now'}, 'templating': {'list': [{'name': 'env', 'type': 'custom', 'query': 'prod.eu,qa+1', 'current': {'text': ['prod.eu', 'qa+1'], 'value': ['prod.eu', 'qa+1']}, 'options': [{'text': 'prod.eu', 'value': 'prod.eu', 'selected': True}, {'text': 'qa+1', 'value': 'qa+1', 'selected': True}], 'multi': True, 'includeAll': False, 'hide': 0, 'refresh': 0}]}, 'panels': [{'id': 1, 'title': 'Requests', 'type': 'timeseries', 'datasource': {'type': 'prometheus', 'uid': 'local-prom'}, 'gridPos': {'x': 0, 'y': 0, 'w': 12, 'h': 8}, 'targets': [{'refId': 'A', 'expr': 'up{env="$env"}', 'range': True, 'instant': False}], 'fieldConfig': {'defaults': {'unit': 'short', 'custom': {}}, 'overrides': []}, 'options': {}}], 'links': []}, 'matcher-cases.json': {}}
d=load('dashboard.json');base=copy.deepcopy(BASE['dashboard.json'])
expr=d['panels'][0]['targets'][0]['expr'];d['panels'][0]['targets'][0]['expr']=base['panels'][0]['targets'][0]['expr'];assert d==base
match=re.fullmatch(r'\s*up\s*\{\s*env\s*=~\s*"(\$env|\$\{env\})"\s*\}\s*',expr)
assert match,'Use a whole-label Prometheus regex matcher and supported escaped multi-value interpolation.'
v=base['templating']['list'][0];assert v['multi'] is True and v['includeAll'] is False
values=v['current']['value'];regex='(?:'+'|'.join(re.escape(x) for x in values)+')'
cases=load('matcher-cases.json')
assert cases=={'must_match':['prod.eu','qa+1'],'must_not_match':['prodXeu','qaa1','prod.eu.extra','qa+11','dev'],'match_semantics':'whole-label','datasource_query_executed':False}
for text in cases['must_match']:assert re.fullmatch(regex,text)
for text in cases['must_not_match']:assert not re.fullmatch(regex,text)
